-- Turns the sky into an image file. The dome this kit draws is procedural, which is what makes it
-- cheap to author and expensive to sample: a lightmap bake, an offline reflection probe or a project
-- that wants its night sky on the disk as pixels rather than as arithmetic asks for a cubemap. This
-- entry renders the same procedural dome into the six faces of one, so a project can own a night
-- cubemap generated by its own sky instead of a photograph that disagrees with it.
--
-- One run renders one face, because one run captures one frame. A pass that wants the whole cube
-- asks for the six faces one at a time:
--
--   for face in px nx py ny pz nz:
--     CUBE_FACE=$face CUBE_HOUR=23 \
--       quantum-engine.exe --project <project> --scene demos/demo_cubemap \
--       --window 512x512 --screenshot <out>/$face.png --capture-frame 40
--
-- The six tiles then pack into a horizontal cross (4x3) with scripts/assemble_sky_cubemap.py, the
-- shape TextureData::loadCubeMapFromSingleFile reads back through SkyBox:setTexture().
--
-- CUBE_PLAYBACK names a cross to sample instead of rendering the dome. That run is the proof of the
-- face order and of the per-face up vector, so it is worth making even when the cube already looks
-- right: whatever the engine shows back is what every sampler in the scene will read.
--
-- CUBE_HOUR (23) and CUBE_MOON (0.5, full) pick the moment; the moon has to be above the horizon for
-- the cube to hold anything but stars.
--
-- CUBE_DIR="dx dy dz ux uy uz" replaces the face table with any camera at all, which is how a saved
-- cube gets checked for seams instead of for face order.
local Kit = require("demos.kit_demo")

local function number(value, fallback)
    if type(value) == "number" and value == value then return value end
    return fallback
end
local function getenv(name)
    local out = nil
    pcall(function() out = os.getenv(name) end)
    return out
end

-- The six faces and the up vector each one is stored with. Measured, not copied from a textbook: a
-- horizon view of a loaded cube returns the tile exactly as it was packed, top edge pointing at
-- world +Y, so a face has to be captured that way. The up vectors the engine uses to build a point
-- light's shadow cube (RenderSystem.cpp:9557) keep -Y as up on the side faces, and a cross cut from
-- those reads back as a sky with its moon under the ground -- still a perfect round trip, which is
-- what makes the mistake invisible unless someone asks where the light is.
local FACES = {
    px = { dir = Vector3( 1.0,  0.0,  0.0), up = Vector3( 0.0,  1.0,  0.0) },
    nx = { dir = Vector3(-1.0,  0.0,  0.0), up = Vector3( 0.0,  1.0,  0.0) },
    py = { dir = Vector3( 0.0,  1.0,  0.0), up = Vector3( 0.0,  0.0, -1.0) },
    ny = { dir = Vector3( 0.0, -1.0,  0.0), up = Vector3( 0.0,  0.0,  1.0) },
    pz = { dir = Vector3( 0.0,  0.0,  1.0), up = Vector3( 0.0,  1.0,  0.0) },
    nz = { dir = Vector3( 0.0,  0.0, -1.0), up = Vector3( 0.0,  1.0,  0.0) },
}

-- CUBE_DIR="dx dy dz ux uy uz" aims at anything at all. A face table cannot prove the cube is
-- seamless: the two faces meeting at a corner have to be checked from a view that lands in both,
-- which is what a diagonal direction with the horizon's own up does.
local function aim(getenv)
    local raw = getenv("CUBE_DIR")
    if not raw then return nil end
    local v = {}
    for token in string.gmatch(raw, "[^,%s]+") do v[#v + 1] = tonumber(token) end
    if #v ~= 6 then
        print("[cubemap] CUBE_DIR wants six numbers: dx dy dz ux uy uz")
        return nil
    end
    return { dir = Vector3(v[1], v[2], v[3]), up = Vector3(v[4], v[5], v[6]) }
end

Kit.start(function()
    local faceName = getenv("CUBE_FACE") or "pz"
    local face = aim(getenv) or FACES[faceName]
    if not face then
        print("[cubemap] CUBE_FACE must be one of px nx py ny pz nz (got " .. faceName .. ")")
        System.quit()
        return
    end
    local playback = getenv("CUBE_PLAYBACK")

    local scene = Kit.createScene()
    scene.backgroundColor = Vector4(0.0, 0.0, 0.0, 1.0)

    local sky = Kit.hold(SkyBox(scene))
    sky.name = "Sky"

    -- No terrain and no water: a sky cubemap has to be pure dome, or the ground bleeds into -Y and
    -- into the horizon band of the four side faces.
    local camera = Kit.hold(Camera(scene))
    camera.name = "Camera"
    camera.position = Vector3(0, 0, 0)
    scene:setCamera(camera)
    -- 90 degrees is the only cone that tiles a cube without overlap or gap. The window is square, so
    -- autoResize leaves the aspect at 1 and the vertical field is also the horizontal one.
    Kit.camera3D(camera, 90, 0.1, 4000)
    camera.up = face.up
    camera.target = Vector3(face.dir.x * 100, face.dir.y * 100, face.dir.z * 100)

    if playback then
        -- The stock sky shader multiplies the cube by the sky's own colour, and the clock spends the
        -- night writing a dark blue into it - a cubemap that already contains the night would come
        -- back multiplied away to black. So this branch runs with no clock at all: the image is the
        -- sky, and white leaves it as authored.
        sky:setTexture(playback)
        sky.color = Vector4(1.0, 1.0, 1.0, 1.0)
        print(string.format("[cubemap] playback face=%s map=%s", faceName, playback))
    else
        -- The rel path is what becomes the .sdat filename, so it has to match the copy the project
        -- ships in assets/shaders/ - the runtime never compiles a shader, it only reads the built one.
        sky.customShader = "assets/shaders/sky_daynight"

        local sun = Kit.hold(Light(scene))
        sun.name = "Sun"
        sun:setType(LightType.DIRECTIONAL)
        local moonLamp = Kit.hold(Light(scene))
        moonLamp.name = "Moon"
        moonLamp:setType(LightType.DIRECTIONAL)
        moonLamp:setIntensity(0.0)

        local hour = number(tonumber(getenv("CUBE_HOUR")), 23.0)
        local cycle = Kit.attach(Kit.module("DayNightCycle"), scene,
            Kit.spawn(scene, "Cycle", 0, 0, 0), {
                light = sun.entity, moonLight = moonLamp.entity, sky = sky.entity,
                dayLength = 240.0, startHour = hour, maxIntensity = 1.35, moonIntensity = 0.30,
                moonPhase = number(tonumber(getenv("CUBE_MOON")), 0.5), sunTilt = 23.5,
                skyBrightness = 1.0
            })
        Kit.attach(Kit.module("Clouds"), scene, Kit.spawn(scene, "Clouds", 0, 0, 0), {
            sky = sky.entity, preset = getenv("CUBE_PRESET") or "clear"
        })

        -- Paused and stepped before the first frame, because a clock that runs would put a different
        -- hour in each face of one cube.
        cycle:setTime(hour)
        cycle:setPaused(true)
        cycle:onUpdate()

        local illumination = 0.0
        pcall(function() illumination = cycle:getIllumination() end)
        print(string.format("[cubemap] capture face=%s hour=%s up=(%g, %g, %g) moon %+5.1f deg %2.0f%% lit",
            faceName, cycle:getHourText(), face.up.x, face.up.y, face.up.z,
            cycle:getMoonElevation(), illumination * 100.0))
    end

    Kit.report("cubemap")
    Kit.watch("cubemap", 4.0)
end)
